import React from 'react';
import { render } from 'react-dom';

class Toggle extends React.Component {
  state = {
    toggled: false,
  };

  handleToggle = () => {
    this.setState(prevState => ({
      toggled: !prevState.toggled,
    }));
  };

  render() {
    const { toggled } = this.state;
    return (
      <div className="bx--form-item">
        <input
          type="checkbox"
          id="toggle-1"
          className="bx--toggle"
          checked={toggled}
          onChange={this.handleToggle}
        />
        <label className="bx--toggle__label" htmlFor="toggle-1">
          <span className="bx--toggle__text--left" aria-hidden="true">
            Off
          </span>
          <span className="bx--toggle__appearance"></span>
          <span className="bx--toggle__text--right" aria-hidden="true">
            On
          </span>
        </label>
      </div>
    );
  }
}

render(<Toggle />, document.getElementById('root'));
